package main

import (
	"context"
	"encoding/hex"
	"testing"

	"github.com/diwise/iot-agent/pkg/lwm2m"
	"github.com/diwise/service-chassis/pkg/infrastructure/o11y/logging"
	"github.com/matryer/is"
)

func TestDecodePayload_WaterMeterReadings(t *testing.T) {
	is := is.New(t)
	logger := testLogger()
	ctx := logging.NewContextWithLogger(context.Background(), logger)

	tests := []struct {
		name           string
		hexPayload     string
		expectedDevice string
		expectedVolume float64
		expectedFlow   *float64
		expectedTemp   *float64
	}{
		{
			name:           "Payload 1",
			hexPayload:     "",
			expectedDevice: "05597622",
			expectedVolume: 0,
			expectedFlow:   nil,
			expectedTemp:   nil,
		},
		{
			name:           "Payload 6",
			hexPayload:     "",
			expectedDevice: "05597622",
			expectedVolume: 0,
			expectedFlow:   nil,
			expectedTemp:   nil,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			is := is.New(t)

			payload, err := hex.DecodeString(tt.hexPayload)
			is.NoErr(err)

			obj, err := decodePayload(ctx, payload)
			is.NoErr(err)
			is.True(obj != nil)

			waterMeter, ok := obj.(lwm2m.WaterMeter)
			is.True(ok) // Should be a WaterMeter type

			is.Equal(waterMeter.ID(), tt.expectedDevice)

			is.Equal(waterMeter.CumulatedWaterVolume, tt.expectedVolume)

			if tt.expectedFlow != nil {
				is.True(waterMeter.MinimumFlowRate != nil)
				is.True(waterMeter.MaximumFlowRate != nil)
				is.Equal(*waterMeter.MinimumFlowRate, *tt.expectedFlow)
				is.Equal(*waterMeter.MaximumFlowRate, *tt.expectedFlow)
			}
		})
	}
}

func TestDecodePayload_InvalidPayloads(t *testing.T) {
	is := is.New(t)
	logger := testLogger()
	ctx := logging.NewContextWithLogger(context.Background(), logger)

	tests := []struct {
		name        string
		hexPayload  string
		expectError string
	}{
		{
			name:        "Payload too small",
			hexPayload:  "0100",
			expectError: "payload size is too small",
		},
		{
			name:        "Invalid telegram type",
			hexPayload:  "FFFF" + "",
			expectError: "unknown telegram type",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			is := is.New(t)

			payload, err := hex.DecodeString(tt.hexPayload)
			is.NoErr(err)

			obj, err := decodePayload(ctx, payload)
			is.True(err != nil)
			is.True(obj == nil)
			is.True(err.Error() != "")
		})
	}
}

func TestDecodePayload_KnownWaterMeterValues(t *testing.T) {
	is := is.New(t)
	logger := testLogger()
	ctx := logging.NewContextWithLogger(context.Background(), logger)

	hexPayload := ""

	payload, err := hex.DecodeString(hexPayload)
	is.NoErr(err)

	obj, err := decodePayload(ctx, payload)
	is.NoErr(err)

	waterMeter, ok := obj.(lwm2m.WaterMeter)
	is.True(ok)

	expectedDeviceID := "05597622"
	is.Equal(waterMeter.ID(), expectedDeviceID)

	expectedVolume := 0.0
	is.Equal(waterMeter.CumulatedWaterVolume, expectedVolume)
	is.True(!waterMeter.Timestamp().IsZero())

	t.Logf("Successfully decoded water meter: ID=%s, Volume=%f, Timestamp=%s",
		waterMeter.ID(), waterMeter.CumulatedWaterVolume, waterMeter.Timestamp())
}

func TestDecodePayload_AllOriginalPayloads(t *testing.T) {
	is := is.New(t)
	logger := testLogger()
	ctx := logging.NewContextWithLogger(context.Background(), logger)

	// All the hex payloads from the original TestMe
	payloads := []string{
		"",
		"",
		"",
		"",
		"",
		"",
		"",
		"",
	}

	for idx, hexPayload := range payloads {
		t.Run("Payload_"+string(rune('0'+idx)), func(t *testing.T) {
			is := is.New(t)

			payload, err := hex.DecodeString(hexPayload)
			is.NoErr(err)

			obj, err := decodePayload(ctx, payload)
			is.NoErr(err)
			is.True(obj != nil)

			waterMeter, ok := obj.(lwm2m.WaterMeter)
			is.True(ok)
			is.Equal(waterMeter.ID(), waterMeter.ID())

		})
	}
}
